/* Shared WMN POS helpers only. No feature or class-specific business logic belongs here. */
function wmn_user_lang() {
            return String(
                (frappe.boot && frappe.boot.lang) ||
                (frappe.boot && frappe.boot.user && frappe.boot.user.language) ||
                (frappe.session && frappe.session.user_language) ||
                document.documentElement.lang ||
                document.body.getAttribute("lang") ||
                "en"
            ).toLowerCase();
        }

        function wmn_is_arabic() {
            const lang = wmn_user_lang();
            return lang.startsWith("ar") || document.documentElement.dir === "rtl" || document.body.dir === "rtl";
        }

        function wmn_t(en, ar) {
            const text = wmn_is_arabic() ? (ar || en) : en;
            return __(text);
        }

        function wmn_msg(en, ar, values) {
            const text = wmn_t(en, ar);
            if (values && Array.isArray(values)) {
                return __(text, values);
            }
            return text;
        }


        window.getAvailableBatchesForItem = function(batches, itemCode, warehouse = "") {
            const today = frappe.datetime.get_today();
            return (batches || [])
                .filter(b => {
                    if (String(b.item_code || "") !== String(itemCode || "")) return false;
                    if (cint(b.disabled || 0)) return false;
                    if (warehouse && b.warehouse && String(b.warehouse) !== String(warehouse)) return false;
                    if (flt(b.actual_qty || 0) <= 0) return false;
                    if (b.expiry_date && String(b.expiry_date).slice(0, 10) < today) return false;
                    return true;
                })
                .sort((a, b) => {
                    const ea = a.expiry_date || "9999-12-31";
                    const eb = b.expiry_date || "9999-12-31";
                    return String(ea).localeCompare(String(eb));
                });
        };

        window.showBatchSelectionDialog = async function(item, warehouse = "") {
            const batches = !window.wmnPOSOffline?.getAllByIndex
                ? []
                : await window.wmnPOSOffline.getAllByIndex(
                    window.wmnPOSOffline.STORES.batches,
                    "item_code",
                    item.item_code
                );

            const rows = window.getAvailableBatchesForItem(batches, item.item_code, warehouse);

            if (!rows.length) {
                return null;
            }

            return await new Promise((resolve) => {
                const dialog = new frappe.ui.Dialog({
                    title: __("Select Batch No and Quantity"),
                    size: "large",
                    fields: [
                        {
                            fieldtype: "HTML",
                            fieldname: "batch_html",
                            options: `
                                <div class="wmn-batch-select-dialog">
                                    <div style="margin-bottom:10px;color:#6b7280;">
                                        ${frappe.utils.escape_html(item.item_name || item.item_code || "")}
                                    </div>
                                    <div style="max-height:55vh;overflow:auto;border:1px solid #e5e7eb;border-radius:10px;">
                                        <table class="table table-bordered table-hover" style="margin:0;">
                                            <thead style="position:sticky;top:0;background:#f8fafc;z-index:1;">
                                                <tr>
                                                    <th>${__("Batch No")}</th>
                                                    <th>${__("Warehouse")}</th>
                                                    <th>${__("Available Qty")}</th>
                                                    <th>${__("Expiry Date")}</th>
                                                    <th style="width:130px;">${__("Qty")}</th>
                                                    <th style="width:110px;">${__("Action")}</th>
                                                </tr>
                                            </thead>
                                            <tbody>
                                                ${rows.map((b, idx) => {
                                                    const availableQty = flt(b.actual_qty || 0);
                                                    const defaultQty = flt(item.qty || 1) || 1;

                                                    return `
                                                        <tr>
                                                            <td style="font-weight:700;">${frappe.utils.escape_html(b.batch_no || "")}</td>
                                                            <td>${frappe.utils.escape_html(b.warehouse || "")}</td>
                                                            <td>${availableQty}</td>
                                                            <td>${frappe.utils.escape_html(b.expiry_date || "")}</td>
                                                            <td>
                                                                <input type="number"
                                                                    class="form-control input-xs wmn-batch-qty"
                                                                    data-idx="${idx}"
                                                                    min="0.001"
                                                                    step="0.001"
                                                                    value="${defaultQty}">
                                                            </td>
                                                            <td>
                                                                <button type="button"
                                                                    class="btn btn-xs btn-primary wmn-select-batch"
                                                                    data-idx="${idx}">
                                                                    ${__("Select")}
                                                                </button>
                                                            </td>
                                                        </tr>
                                                    `;
                                                }).join("")}
                                            </tbody>
                                        </table>
                                    </div>
                                </div>
                            `
                        }
                    ],
                    secondary_action_label: __("Cancel"),
                    secondary_action: () => {
                        dialog.hide();
                        resolve(null);
                    }
                });

                dialog.$wrapper.addClass("wmn-pos-app-dialog wmn-pos-batch-legacy-dialog");
                dialog.show();

                dialog.$wrapper.on("click", ".wmn-select-batch", function () {
                    const idx = cint($(this).attr("data-idx"));
                    const selected = rows[idx] || null;

                    if (!selected) {
                        dialog.hide();
                        resolve(null);
                        return;
                    }

                    const qtyInput = dialog.$wrapper.find(`.wmn-batch-qty[data-idx="${idx}"]`).val();
                    const qty = flt(qtyInput || 0);
                    const availableQty = flt(selected.actual_qty || 0);

                    if (qty <= 0) {
                        frappe.show_alert({
                            message: __("Quantity must be greater than zero"),
                            indicator: "orange"
                        });
                        return;
                    }

                    const allowNegativeStock = cint(window.cur_pos?.allow_negative_stock || 0) === 1 || cint(item?.allow_negative_stock || selected?.allow_negative_stock || 0) === 1;
                    if (!allowNegativeStock && availableQty >= 0 && qty > availableQty) {
                        frappe.show_alert({
                            message: __("Quantity cannot exceed available batch quantity"),
                            indicator: "orange"
                        });
                        return;
                    }

                    selected.__selected_qty = qty;
                    dialog.hide();
                    resolve(selected);
                });
            });
        };


        function wmn_money(value, currency) {
            const amount = flt(value || 0).toFixed(2);
            return amount + " " + (currency || "");
        }

        function wmn_escape_html(value) {
            return frappe.utils.escape_html(value == null ? "" : String(value));
        }


        function wmn_base64_utf8(value) {
            try {
                return btoa(unescape(encodeURIComponent(String(value || ""))));
            } catch (e) {
                try {
                    return btoa(String(value || ""));
                } catch (_e) {
                    return "";
                }
            }
        }


function wmn_is_mobile_pos_device() {
    return (
        window.innerWidth <= 768 ||
        /Android|iPhone|iPad|iPod|Mobile/i.test(navigator.userAgent)
    );
}

/* Shared async compatibility helper used by multiple ERPNext overrides. */
(function () {
    "use strict";
    const ns = window.WMN_POS = window.WMN_POS || {};
    ns.Common = ns.Common || {};

    ns.Common.asFrappeCallLike = function asFrappeCallLike(promise) {
        const p = Promise.resolve(promise);

        return {
            then(onFulfilled, onRejected) {
                return ns.Common.asFrappeCallLike(p.then(onFulfilled, onRejected));
            },
            catch(onRejected) {
                return ns.Common.asFrappeCallLike(p.catch(onRejected));
            },
            finally(onFinally) {
                return ns.Common.asFrappeCallLike(p.finally(onFinally));
            },
            always(callback) {
                p.then(
                    (value) => {
                        if (callback) callback(value);
                        return value;
                    },
                    (error) => {
                        if (callback) callback(error);
                        throw error;
                    }
                );
                return this;
            },
            done(callback) {
                p.then((value) => {
                    if (callback) callback(value);
                });
                return this;
            },
            fail(callback) {
                p.catch((error) => {
                    if (callback) callback(error);
                });
                return this;
            },
            promise() {
                return p;
            },
        };
    };
})();
/* END support:core/common.js */

/* BEGIN support:services/settings/device_preferences.js */
/* Persistent device-local WMN POS preferences with localStorage + IndexedDB backup. */
(function () {
    "use strict";

    const ns = window.WMN_POS;
    ns.Services.Settings = ns.Services.Settings || {};

    const DB_NAME = "wmnPOSDevicePreferences";
    const DB_VERSION = 1;
    const STORE_NAME = "preferences";
    const registry = new Map();
    const memory = new Map();
    let dbPromise = null;
    let initializePromise = null;
    let initialized = false;

    function clone(value) {
        if (value === undefined) return undefined;
        try { return JSON.parse(JSON.stringify(value)); } catch (e) { return value; }
    }

    function normalizeObject(value, defaults) {
        const base = defaults && typeof defaults === "object" ? clone(defaults) : {};
        const incoming = value && typeof value === "object" && !Array.isArray(value) ? value : {};
        return Object.assign(base || {}, incoming);
    }

    function readLocal(key) {
        try {
            const raw = window.localStorage.getItem(key);
            if (!raw) return null;
            const parsed = JSON.parse(raw);
            return parsed && typeof parsed === "object" ? parsed : null;
        } catch (error) {
            console.warn(`WMN device preference local read failed: ${key}`, error);
            return null;
        }
    }

    function writeLocal(key, value) {
        try {
            window.localStorage.setItem(key, JSON.stringify(value));
            return true;
        } catch (error) {
            console.warn(`WMN device preference local write failed: ${key}`, error);
            return false;
        }
    }

    function openDb() {
        if (!window.indexedDB) return Promise.resolve(null);
        if (dbPromise) return dbPromise;

        dbPromise = new Promise((resolve) => {
            let request;
            try {
                request = window.indexedDB.open(DB_NAME, DB_VERSION);
            } catch (error) {
                console.warn("WMN device preference database could not be opened", error);
                resolve(null);
                return;
            }

            request.onupgradeneeded = () => {
                const db = request.result;
                if (!db.objectStoreNames.contains(STORE_NAME)) {
                    db.createObjectStore(STORE_NAME, { keyPath: "key" });
                }
            };
            request.onsuccess = () => resolve(request.result);
            request.onerror = () => {
                console.warn("WMN device preference database open failed", request.error);
                resolve(null);
            };
        });

        return dbPromise;
    }

    async function readBackup(key) {
        const db = await openDb();
        if (!db) return null;
        return new Promise((resolve) => {
            try {
                const tx = db.transaction(STORE_NAME, "readonly");
                const request = tx.objectStore(STORE_NAME).get(key);
                request.onsuccess = () => resolve(request.result?.value || null);
                request.onerror = () => resolve(null);
            } catch (error) {
                resolve(null);
            }
        });
    }

    async function writeBackup(key, value) {
        const db = await openDb();
        if (!db) return false;
        return new Promise((resolve) => {
            try {
                const tx = db.transaction(STORE_NAME, "readwrite");
                tx.objectStore(STORE_NAME).put({
                    key,
                    value: clone(value),
                    updated_at: new Date().toISOString(),
                });
                tx.oncomplete = () => resolve(true);
                tx.onerror = () => resolve(false);
                tx.onabort = () => resolve(false);
            } catch (error) {
                resolve(false);
            }
        });
    }

    function register(key, defaults) {
        const normalizedKey = String(key || "").trim();
        if (!normalizedKey) throw new Error("WMN device preference key is required");
        registry.set(normalizedKey, clone(defaults || {}));
        return normalizedKey;
    }

    function readSync(key, defaults) {
        const normalizedKey = String(key || "").trim();
        const configuredDefaults = defaults || registry.get(normalizedKey) || {};
        const local = readLocal(normalizedKey);
        if (local) {
            const value = normalizeObject(local, configuredDefaults);
            memory.set(normalizedKey, value);
            return clone(value);
        }
        if (memory.has(normalizedKey)) {
            return clone(normalizeObject(memory.get(normalizedKey), configuredDefaults));
        }
        return normalizeObject({}, configuredDefaults);
    }

    function write(key, value, defaults) {
        const normalizedKey = String(key || "").trim();
        const configuredDefaults = defaults || registry.get(normalizedKey) || {};
        const normalized = normalizeObject(value, configuredDefaults);
        memory.set(normalizedKey, normalized);
        writeLocal(normalizedKey, normalized);
        writeBackup(normalizedKey, normalized).catch((error) => {
            console.warn(`WMN device preference backup write failed: ${normalizedKey}`, error);
        });
        return clone(normalized);
    }

    async function restoreKey(key, defaults) {
        const local = readLocal(key);
        const backup = await readBackup(key);

        if (local) {
            const normalized = normalizeObject(local, defaults);
            memory.set(key, normalized);
            if (!backup || JSON.stringify(backup) !== JSON.stringify(normalized)) {
                await writeBackup(key, normalized);
            }
            return normalized;
        }

        if (backup) {
            const normalized = normalizeObject(backup, defaults);
            memory.set(key, normalized);
            writeLocal(key, normalized);
            return normalized;
        }

        const normalized = normalizeObject({}, defaults);
        memory.set(key, normalized);
        return normalized;
    }

    async function initialize() {
        if (initialized) return true;
        if (initializePromise) return initializePromise;

        initializePromise = (async () => {
            for (const [key, defaults] of registry.entries()) {
                await restoreKey(key, defaults);
            }
            initialized = true;
            window.dispatchEvent(new CustomEvent("wmn:device-preferences-ready"));
            return true;
        })().catch((error) => {
            console.warn("WMN device preference initialization failed; localStorage fallback remains active", error);
            initialized = true;
            return false;
        });

        return initializePromise;
    }

    async function syncRegisteredBackups() {
        for (const [key, defaults] of registry.entries()) {
            const current = readSync(key, defaults);
            await writeBackup(key, current);
        }
        return true;
    }

    ns.Services.Settings.DevicePreferences = {
        DB_NAME,
        STORE_NAME,
        register,
        initialize,
        readSync,
        write,
        syncRegisteredBackups,
        isInitialized() { return initialized; },
    };
})();
/* END support:services/settings/device_preferences.js */

/* BEGIN support:services/settings/pos_profile_settings.js */
/* POS Profile-scoped WMN settings with server defaults and browser-local overrides. */
(function () {
    "use strict";

    const ns = window.WMN_POS;
    ns.Services.Settings = ns.Services.Settings || {};

    const DEFAULTS = Object.freeze({
        ignore_pricing_rule: 0,
        pricing_rule_promotion_policy: "Combine",
        pricing_rule_coupon_policy: "Combine",
        promotion_coupon_policy: "Combine",
        pricing_rule_promotion_coupon_policy: "Combine",
        combined_discount_representation: "Amount Only",
        default_item_view: "Grid View",
        show_item_cart_counter: 0,
        enable_auto_silent_print: 0,
        wmn_silent_print_mode: "raw_text",
        print_after_cashier_completion: 0,
        printing_method: "legacy_bridge",
        fallback_method: "none",
        copies: 1,
        cut_paper: 1,
        feed_lines: 3,
        escpos_initialize: 1,
        show_invoice_barcode: 1,
        invoice_barcode_height: 56,
        invoice_barcode_module_width: 2,
        invoice_barcode_human_readable: 1,
        qz_printer_name: "",
        qz_connector_mode: "legacy",
        qz_connector_url: "",
        qz_host: "",
        qz_encoding: "UTF8",
        bridge_ws_url: "ws://127.0.0.1:12212/printer",
        webusb_vendor_id: "",
        webusb_product_id: "",
        webusb_serial_number: "",
        webusb_device_label: "",
        webserial_vendor_id: "",
        webserial_product_id: "",
        webserial_device_label: "",
        webserial_baud_rate: 9600,
        webserial_data_bits: 8,
        webserial_stop_bits: 1,
        webserial_parity: "none",
        webserial_flow_control: "none",
    });

    const NUMERIC_KEYS = new Set([
        "ignore_pricing_rule",
        "show_item_cart_counter",
        "enable_auto_silent_print",
        "print_after_cashier_completion",
        "copies",
        "cut_paper",
        "feed_lines",
        "escpos_initialize",
        "show_invoice_barcode",
        "invoice_barcode_height",
        "invoice_barcode_module_width",
        "invoice_barcode_human_readable",
        "webserial_baud_rate",
        "webserial_data_bits",
        "webserial_stop_bits",
    ]);

    // Business-critical profile flags must never diverge per browser/device.
    const SERVER_ONLY_KEYS = new Set([
        "ignore_pricing_rule",
        "pricing_rule_promotion_policy",
        "pricing_rule_coupon_policy",
        "promotion_coupon_policy",
        "pricing_rule_promotion_coupon_policy",
        "combined_discount_representation",
    ]);

    let currentProfile = "";
    let currentServerState = null;
    let bootstrapPromise = null;

    function clone(value) {
        try { return JSON.parse(JSON.stringify(value)); } catch (e) { return value; }
    }

    function keyPart(profile) {
        return encodeURIComponent(String(profile || "").trim());
    }

    function serverCacheKey(profile) {
        return `wmn_pos_profile_settings_server_v1::${keyPart(profile)}`;
    }

    function localOverrideKey(profile) {
        return `wmn_pos_profile_settings_local_v1::${keyPart(profile)}`;
    }

    function readJson(key, fallback) {
        try {
            const raw = localStorage.getItem(key);
            if (!raw) return clone(fallback);
            const parsed = JSON.parse(raw);
            return parsed && typeof parsed === "object" ? parsed : clone(fallback);
        } catch (e) {
            return clone(fallback);
        }
    }

    function writeJson(key, value) {
        try {
            localStorage.setItem(key, JSON.stringify(value || {}));
            return true;
        } catch (e) {
            console.warn("WMN POS Profile settings local write failed", e);
            return false;
        }
    }

    function removeJson(key) {
        try { localStorage.removeItem(key); } catch (e) {}
    }

    function normalize(settings) {
        const out = {};
        Object.entries(settings || {}).forEach(([key, value]) => {
            if (!(key in DEFAULTS)) return;
            if (NUMERIC_KEYS.has(key)) {
                const num = Number(value);
                out[key] = Number.isFinite(num) ? num : Number(DEFAULTS[key] || 0);
            } else {
                out[key] = value == null ? DEFAULTS[key] : String(value);
            }
        });
        return out;
    }

    function isOnline() {
        try {
            if (typeof wmn_is_pos_offline === "function" && wmn_is_pos_offline()) return false;
            if (window.__wmn_pos_effective_offline === true) return false;
        } catch (e) {}
        return navigator.onLine !== false;
    }

    function resolveProfile(explicitProfile) {
        return String(
            explicitProfile ||
            currentProfile ||
            window.cur_pos?.pos_profile ||
            window.cur_pos?.settings?.pos_profile ||
            window.cur_pos?.frm?.doc?.pos_profile ||
            ""
        ).trim();
    }

    function readServerState(profile) {
        const normalizedProfile = resolveProfile(profile);
        if (!normalizedProfile) return { available: false, pos_profile: "", settings: {}, can_write: false };
        if (normalizedProfile === currentProfile && currentServerState) return clone(currentServerState);
        return readJson(serverCacheKey(normalizedProfile), {
            available: false,
            pos_profile: normalizedProfile,
            settings: {},
            can_write: false,
        });
    }

    function writeServerState(profile, state) {
        const normalizedProfile = resolveProfile(profile);
        const normalized = Object.assign(
            { available: false, pos_profile: normalizedProfile, settings: {}, can_write: false },
            state || {},
            {
                pos_profile: normalizedProfile,
                settings: normalize(state?.settings || {}),
                cached_at: new Date().toISOString(),
            }
        );
        writeJson(serverCacheKey(normalizedProfile), normalized);
        if (normalizedProfile === currentProfile) currentServerState = normalized;
        return clone(normalized);
    }

    function getLocalOverride(profile) {
        const normalizedProfile = resolveProfile(profile);
        if (!normalizedProfile) return {};
        const local = normalize(readJson(localOverrideKey(normalizedProfile), {}));
        SERVER_ONLY_KEYS.forEach((key) => delete local[key]);
        return local;
    }

    function getServerSettings(profile) {
        return normalize(readServerState(profile).settings || {});
    }

    function getEffective(profile) {
        const normalizedProfile = resolveProfile(profile);
        return Object.assign(
            {},
            DEFAULTS,
            getServerSettings(normalizedProfile),
            getLocalOverride(normalizedProfile)
        );
    }


    function migrateLegacyBrowserSettings(profile) {
        const normalizedProfile = resolveProfile(profile);
        if (!normalizedProfile) return;
        const markerKey = `wmn_pos_profile_settings_migrated_v1::${keyPart(normalizedProfile)}`;
        try {
            if (localStorage.getItem(markerKey)) return;
        } catch (e) {}

        const patch = {};
        try {
            const rawPrint = localStorage.getItem("wmn_pos_print_transport_v1");
            const legacyPrint = rawPrint ? JSON.parse(rawPrint) : {};
            if (legacyPrint && typeof legacyPrint === "object") {
                const map = { method: "printing_method" };
                Object.entries(legacyPrint).forEach(([key, value]) => {
                    const target = map[key] || key;
                    if (target in DEFAULTS) patch[target] = value;
                });
            }
        } catch (e) {}

        try {
            const rawUI = localStorage.getItem("wmn_pos_ui_preferences_v1");
            const legacyUI = rawUI ? JSON.parse(rawUI) : {};
            if (legacyUI && Object.prototype.hasOwnProperty.call(legacyUI, "show_item_cart_counter")) {
                patch.show_item_cart_counter = legacyUI.show_item_cart_counter ? 1 : 0;
            }
            const buttonMode = localStorage.getItem("wmn_pos_button_mode");
            if (buttonMode === "true" || buttonMode === "false") {
                patch.default_item_view = buttonMode === "true" ? "Button View" : "Grid View";
            }
        } catch (e) {}

        if (Object.keys(patch).length && !Object.keys(getLocalOverride(normalizedProfile)).length) {
            writeJson(localOverrideKey(normalizedProfile), normalize(patch));
        }
        try { localStorage.setItem(markerKey, "1"); } catch (e) {}
    }

    async function refresh(profile) {
        const normalizedProfile = resolveProfile(profile);
        if (!normalizedProfile || !isOnline()) return readServerState(normalizedProfile);
        const response = await frappe.call({
            method: "wmn.wmn.page.wmn_pos.wmn_pos.get_pos_profile_settings",
            args: { pos_profile: normalizedProfile },
            freeze: false,
        });
        return writeServerState(normalizedProfile, response?.message || {});
    }

    async function bootstrap(profile) {
        const normalizedProfile = resolveProfile(profile);
        if (!normalizedProfile) return getEffective("");

        if (currentProfile !== normalizedProfile) {
            currentProfile = normalizedProfile;
            migrateLegacyBrowserSettings(normalizedProfile);
            currentServerState = readServerState(normalizedProfile);
            bootstrapPromise = null;
        }

        if (bootstrapPromise) return bootstrapPromise;
        bootstrapPromise = (async () => {
            if (isOnline()) {
                try { await refresh(normalizedProfile); }
                catch (error) {
                    console.warn("WMN POS Profile settings refresh failed; cached settings remain active", error);
                }
            }
            window.dispatchEvent(new CustomEvent("wmn:pos-profile-settings-ready", {
                detail: { pos_profile: normalizedProfile, settings: getEffective(normalizedProfile) },
            }));
            return getEffective(normalizedProfile);
        })();
        return bootstrapPromise;
    }

    function saveLocalPatch(patch, profile) {
        const normalizedProfile = resolveProfile(profile);
        if (!normalizedProfile) throw new Error("POS Profile is required before saving browser settings.");
        const current = getLocalOverride(normalizedProfile);
        const normalizedPatch = normalize(patch || {});
        SERVER_ONLY_KEYS.forEach((key) => delete normalizedPatch[key]);
        const next = Object.assign({}, current, normalizedPatch);
        writeJson(localOverrideKey(normalizedProfile), next);
        window.dispatchEvent(new CustomEvent("wmn:pos-profile-settings-changed", {
            detail: { pos_profile: normalizedProfile, source: "browser", settings: getEffective(normalizedProfile) },
        }));
        return getEffective(normalizedProfile);
    }

    function clearLocalKeys(keys, profile) {
        const normalizedProfile = resolveProfile(profile);
        if (!normalizedProfile) return {};
        const current = getLocalOverride(normalizedProfile);
        (keys || []).forEach((key) => delete current[key]);
        if (Object.keys(current).length) writeJson(localOverrideKey(normalizedProfile), current);
        else removeJson(localOverrideKey(normalizedProfile));
        return current;
    }

    async function saveServerPatch(patch, profile) {
        const normalizedProfile = resolveProfile(profile);
        if (!normalizedProfile) throw new Error("POS Profile is required before saving server settings.");
        if (!isOnline()) throw new Error(__("Cannot save POS Profile Settings while offline."));
        const normalizedPatch = normalize(patch || {});
        const response = await frappe.call({
            method: "wmn.wmn.page.wmn_pos.wmn_pos.save_pos_profile_settings",
            args: { pos_profile: normalizedProfile, values: normalizedPatch },
            freeze: false,
        });
        writeServerState(normalizedProfile, response?.message || {});
        clearLocalKeys(Object.keys(normalizedPatch), normalizedProfile);
        window.dispatchEvent(new CustomEvent("wmn:pos-profile-settings-changed", {
            detail: { pos_profile: normalizedProfile, source: "server", settings: getEffective(normalizedProfile) },
        }));
        return getEffective(normalizedProfile);
    }

    function status(profile) {
        const normalizedProfile = resolveProfile(profile);
        const server = readServerState(normalizedProfile);
        return {
            pos_profile: normalizedProfile,
            online: isOnline(),
            available: !!server.available,
            can_write: !!server.can_write,
            modified: server.modified || "",
            cached_at: server.cached_at || "",
            has_local_override: Object.keys(getLocalOverride(normalizedProfile)).length > 0,
        };
    }

    function isLocalPricingRuleEngineIgnored(profile) {
        const effective = getEffective(profile);
        return cint(effective.ignore_pricing_rule || 0) === 1;
    }

    function applyLegacySettings(target, profile) {
        const effective = getEffective(profile);
        target = target || {};
        target.enable_auto_silent_print = cint(effective.enable_auto_silent_print || 0);
        target.wmn_silent_print_mode = effective.wmn_silent_print_mode || "raw_text";
        return target;
    }

    ns.Services.Settings.POSProfileSettings = {
        DEFAULTS,
        bootstrap,
        refresh,
        getEffective,
        getServerSettings,
        getLocalOverride,
        saveLocalPatch,
        saveServerPatch,
        clearLocalKeys,
        status,
        isOnline,
        resolveProfile,
        applyLegacySettings,
        isLocalPricingRuleEngineIgnored,
    };
})();
/* END support:services/settings/pos_profile_settings.js */

