/* BEGIN support:features/invoice_barcode/invoice_barcode.common.js */
/* Invoice barcode feature facade. */
(function () {
    "use strict";

    const ns = window.WMN_POS;
    ns.Features.InvoiceBarcode = ns.Features.InvoiceBarcode || {};

    function isOffline() {
        try {
            if (typeof wmn_is_pos_offline === "function" && wmn_is_pos_offline()) return true;
            if (window.__wmn_pos_effective_offline === true) return true;
            return navigator.onLine === false;
        } catch (e) {
            return navigator.onLine === false;
        }
    }

    function openInvoiceDocument(doc) {
        if (!doc) return false;
        const ctrl = window.cur_pos;
        if (!ctrl?.order_summary?.load_summary_of) {
            throw new Error("WMN POS order summary is not available");
        }

        if (typeof ctrl.toggle_recent_order_list === "function") {
            ctrl.toggle_recent_order_list(true);
        }
        ctrl.order_summary.load_summary_of(doc, false);
        return true;
    }

    async function findByBarcode(value) {
        const service = ns.Services?.Barcode?.InvoiceBarcode;
        const lookup = service?.parseLookup?.(value) || null;
        if (!lookup) {
            return { handled: false, lookup: null, uid: "", doc: null };
        }

        const adapter = isOffline()
            ? ns.Features.InvoiceBarcode.Offline
            : ns.Features.InvoiceBarcode.Online;

        if (!adapter?.findByLookup) {
            throw new Error("WMN invoice barcode adapter is not available");
        }

        const doc = await adapter.findByLookup(lookup);
        return {
            handled: true,
            lookup,
            uid: lookup.type === "uid" ? lookup.uid : "",
            doc: doc || null,
        };
    }

    async function handleScan(value) {
        const result = await findByBarcode(value);
        if (!result.handled) return false;
        if (!result.doc) {
            frappe.show_alert({
                message: __("Invoice barcode was not found"),
                indicator: "orange",
            });
            return true;
        }

        openInvoiceDocument(result.doc);
        frappe.show_alert({
            message: __("Invoice {0} opened", [result.doc.name || result.doc.wmn_receipt_no || result.uid || String(value || "")]),
            indicator: "green",
        });
        return true;
    }

    ns.Features.InvoiceBarcode.Common = {
        isOffline,
        isInvoiceBarcode(value) {
            return !!ns.Services?.Barcode?.InvoiceBarcode?.isInvoiceBarcode?.(value);
        },
        ensureInvoiceUID(doc) {
            return ns.Services?.Barcode?.InvoiceBarcode?.ensureInvoiceUID?.(doc) || "";
        },
        openInvoiceDocument,
        findByBarcode,
        handleScan,
    };
})();
/* END support:features/invoice_barcode/invoice_barcode.common.js */

/* BEGIN support:features/invoice_barcode/invoice_barcode.online.js */
/* Online invoice barcode lookup uses receipt-opening identity, with legacy UID compatibility. */
(function () {
    "use strict";

    const ns = window.WMN_POS;
    ns.Features.InvoiceBarcode = ns.Features.InvoiceBarcode || {};

    function syncDoc(doc) {
        if (!doc) return null;
        if (window.frappe?.model?.sync) {
            frappe.model.sync(doc);
            return frappe.get_doc(doc.doctype, doc.name) || doc;
        }
        return doc;
    }

    ns.Features.InvoiceBarcode.Online = {
        async findByLookup(lookup) {
            if (!lookup) return null;

            const method = lookup.type === "receipt"
                ? "wmn.invoice_barcode.get_invoice_by_receipt"
                : "wmn.invoice_barcode.get_invoice_by_uid";
            const args = lookup.type === "receipt"
                ? {
                    pos_opening_entry: lookup.pos_opening_entry,
                    receipt_no: lookup.receipt_no,
                }
                : { invoice_uid: lookup.uid };

            const response = await frappe.call({ method, args, freeze: false });
            return syncDoc(response?.message || null);
        },

        async findByUID(uid) {
            return this.findByLookup({ type: "uid", uid });
        },
    };
})();
/* END support:features/invoice_barcode/invoice_barcode.online.js */

/* BEGIN support:features/invoice_barcode/invoice_barcode.offline.js */
/* Offline invoice barcode lookup reads only the local invoice queue. */
(function () {
    "use strict";

    const ns = window.WMN_POS;
    ns.Features.InvoiceBarcode = ns.Features.InvoiceBarcode || {};

    function invoiceFromRow(row) {
        return row?.invoice || row?.doc || row?.data || row || {};
    }

    function matchesLookup(row, lookup) {
        const doc = invoiceFromRow(row);
        if (lookup.type === "receipt") {
            const opening = String(
                doc.wmn_receipt_opening_entry ||
                doc.pos_opening_entry ||
                doc.pos_opening ||
                doc.opening_entry ||
                ""
            ).trim().toUpperCase();
            const receipt = String(doc.wmn_receipt_no || doc.__wmn_receipt_no || "")
                .trim()
                .padStart(5, "0");
            return opening === String(lookup.pos_opening_entry || "").trim().toUpperCase()
                && receipt === String(lookup.receipt_no || "").trim();
        }

        return String(doc.wmn_invoice_uid || "").trim().toUpperCase()
            === String(lookup.uid || "").trim().toUpperCase();
    }

    ns.Features.InvoiceBarcode.Offline = {
        async findByLookup(lookup) {
            if (!lookup || !window.wmnPOSOffline?.STORES?.invoice_queue) return null;
            const readAll = window.wmnPOSOffline.getAllCached || window.wmnPOSOffline.getAll;
            if (!readAll) return null;

            const rows = await readAll(window.wmnPOSOffline.STORES.invoice_queue);
            const match = (rows || []).find((row) => matchesLookup(row, lookup));
            if (!match) return null;

            if (typeof window.wmnPOSOffline.decorateInvoiceQueueRow === "function") {
                const paymentRows = window.wmnPOSOffline.STORES?.payment_entry_queue
                    ? await readAll(window.wmnPOSOffline.STORES.payment_entry_queue)
                    : [];
                return window.wmnPOSOffline.decorateInvoiceQueueRow(match, paymentRows || []);
            }

            return JSON.parse(JSON.stringify(invoiceFromRow(match)));
        },

        async findByUID(uid) {
            return this.findByLookup({ type: "uid", uid });
        },
    };
})();
/* END support:features/invoice_barcode/invoice_barcode.offline.js */

/* BEGIN support:features/invoice_handoff/invoice_handoff.common.js */
/* Cashier handoff lifecycle for draft POS invoices. */
(function () {
    "use strict";

    const ns = window.WMN_POS;
    ns.Features.InvoiceHandoff = ns.Features.InvoiceHandoff || {};

    const AWAITING_CASHIER = "AWAITING_CASHIER";
    const STAGE_FIELD = "wmn_pos_stage";
    const SENT_AT_FIELD = "wmn_sent_to_cashier_at";

    function isOffline(ctrl) {
        try {
            if (typeof wmn_controller_uses_offline_flow === "function" && ctrl) {
                return !!wmn_controller_uses_offline_flow(ctrl);
            }
        } catch (e) {}
        try {
            if (typeof wmn_is_pos_offline === "function") return !!wmn_is_pos_offline();
        } catch (e) {}
        return window.__wmn_pos_effective_offline === true || navigator.onLine === false;
    }

    function isAwaitingCashier(doc) {
        return String(doc?.[STAGE_FIELD] || "").trim() === AWAITING_CASHIER;
    }

    function canSendToCashier(doc) {
        doc = doc || {};
        if (cint(doc.docstatus || 0) !== 0) return false;
        if (cint(doc.is_return || 0) === 1) return false;
        return Array.isArray(doc.items) && doc.items.length > 0;
    }

    function nowDatetime() {
        if (window.frappe?.datetime?.now_datetime) return frappe.datetime.now_datetime();
        return new Date().toISOString().slice(0, 19).replace("T", " ");
    }

    function markAwaitingCashier(doc) {
        if (!doc) return doc;
        doc[STAGE_FIELD] = AWAITING_CASHIER;
        doc[SENT_AT_FIELD] = nowDatetime();
        doc.__wmn_saved_as_draft = true;
        return doc;
    }

    function prepareForCompletion(doc) {
        if (!doc) return doc;
        doc[STAGE_FIELD] = "";
        if (String(doc.status || "").trim() === "Awaiting Cashier") {
            doc.status = "Draft";
        }
        delete doc.__wmn_saved_as_draft;
        delete doc.__wmn_display_status;
        return doc;
    }

    function capturePaymentSnapshot(doc) {
        doc = doc || {};
        return {
            paid_amount: doc.paid_amount,
            base_paid_amount: doc.base_paid_amount,
            change_amount: doc.change_amount,
            base_change_amount: doc.base_change_amount,
            payments: (doc.payments || []).map((row) => ({
                name: row.name || "",
                mode_of_payment: row.mode_of_payment || "",
                account: row.account || "",
                amount: row.amount,
                base_amount: row.base_amount,
            })),
        };
    }

    function restorePaymentSnapshot(doc, snapshot) {
        if (!doc || !snapshot) return doc;
        const used = new Set();
        (doc.payments || []).forEach((row) => {
            let source = snapshot.payments.find((saved, index) => {
                if (used.has(index)) return false;
                if (saved.name && row.name && saved.name === row.name) return true;
                return saved.mode_of_payment === (row.mode_of_payment || "") &&
                    saved.account === (row.account || "");
            });
            if (!source) return;
            const index = snapshot.payments.indexOf(source);
            if (index >= 0) used.add(index);
            row.amount = source.amount;
            row.base_amount = source.base_amount;
        });
        doc.paid_amount = snapshot.paid_amount;
        doc.base_paid_amount = snapshot.base_paid_amount;
        doc.change_amount = snapshot.change_amount;
        doc.base_change_amount = snapshot.base_change_amount;
        return doc;
    }

    async function ensureIdentity(doc) {
        const barcode = ns.Services?.Barcode?.InvoiceBarcode;
        if (barcode?.ensureInvoiceUID) barcode.ensureInvoiceUID(doc);
        if (typeof wmn_assign_receipt_number === "function") {
            await wmn_assign_receipt_number(doc);
        }
        return doc;
    }

    async function printHandoff(doc) {
        if (typeof wmn_print_raw_receipt !== "function") {
            throw new Error("WMN receipt printing service is not available");
        }
        return await wmn_print_raw_receipt(doc);
    }

    async function resetToNewOrder(ctrl) {
        ctrl.__wmn_cashier_resume = false;
        ctrl.payment?.toggle_component?.(false);
        ctrl.order_summary?.toggle_component?.(false);
        ctrl.recent_order_list?.toggle_component?.(false);

        await ctrl.make_new_invoice();

        ctrl.item_selector?.toggle_component?.(true);
        ctrl.cart?.toggle_component?.(true);
        ctrl.cart?.$numpad_section?.css?.("display", "none");
        ctrl.cart?.$totals_section?.css?.("display", "flex");
        ctrl.item_selector?.sync_card_quantities?.();
    }

    async function sendToCashier(ctrl) {
        if (!ctrl?.frm?.doc) throw new Error("No open POS invoice");
        if (ctrl.__wmn_handoff_in_flight) return false;

        const doc = ctrl.frm.doc;
        if (!canSendToCashier(doc)) {
            frappe.show_alert({
                message: wmn_t("This invoice cannot be sent to cashier.", "لا يمكن إرسال هذه الفاتورة إلى الكاشير."),
                indicator: "orange",
            });
            return false;
        }

        ctrl.__wmn_handoff_in_flight = true;
        try {
            await ensureIdentity(doc);
            markAwaitingCashier(doc);

            const adapter = isOffline(ctrl)
                ? ns.Features.InvoiceHandoff.Offline
                : ns.Features.InvoiceHandoff.Online;
            if (!adapter?.saveDraft) throw new Error("WMN cashier handoff adapter is not available");

            const savedDoc = await adapter.saveDraft(ctrl, doc);

            try {
                await printHandoff(savedDoc || doc);
            } catch (printError) {
                frappe.msgprint({
                    title: wmn_t("Cashier Handoff Saved", "تم حفظ الإرسال للكاشير"),
                    indicator: "orange",
                    message: wmn_t(
                        "The draft was saved for the cashier, but printing failed. Retry Send to Cashier to print it before starting a new order.",
                        "تم حفظ المسودة للكاشير، لكن الطباعة فشلت. أعد الضغط على إرسال إلى الكاشير لطباعة السند قبل بدء طلب جديد."
                    ) + "<br><br>" + frappe.utils.escape_html(printError?.message || String(printError)),
                });
                throw printError;
            }

            if (ctrl.recent_order_list?.refresh_list) {
                try { await ctrl.recent_order_list.refresh_list(); } catch (e) {}
            }

            await resetToNewOrder(ctrl);
            frappe.show_alert({
                message: wmn_t("Invoice sent to cashier and printed.", "تم إرسال الفاتورة إلى الكاشير وطباعتها."),
                indicator: "green",
            });
            return true;
        } finally {
            ctrl.__wmn_handoff_in_flight = false;
        }
    }

    ns.Features.InvoiceHandoff.Common = {
        AWAITING_CASHIER,
        STAGE_FIELD,
        SENT_AT_FIELD,
        isOffline,
        isAwaitingCashier,
        canSendToCashier,
        markAwaitingCashier,
        prepareForCompletion,
        capturePaymentSnapshot,
        restorePaymentSnapshot,
        sendToCashier,
    };
})();
/* END support:features/invoice_handoff/invoice_handoff.common.js */

/* BEGIN support:features/invoice_handoff/invoice_handoff.online.js */
/* Online adapter for cashier handoff draft persistence. */
(function () {
    "use strict";

    const ns = window.WMN_POS;
    ns.Features.InvoiceHandoff = ns.Features.InvoiceHandoff || {};

    ns.Features.InvoiceHandoff.Online = {
        async saveDraft(ctrl, doc) {
            if (!ctrl?.frm?.save) throw new Error("POS form save is not available");

            const stageField = ns.Features.InvoiceHandoff.Common?.STAGE_FIELD || "wmn_pos_stage";
            if (window.frappe?.meta?.get_field && !frappe.meta.get_field(doc.doctype, stageField)) {
                throw new Error("WMN cashier handoff fields are missing. Run bench migrate.");
            }

            ctrl.frm.dirty?.();
            await ctrl.frm.save();
            const saved = ctrl.frm.doc || doc;
            if (cint(saved.docstatus || 0) !== 0) {
                throw new Error("Cashier handoff must remain a Draft invoice");
            }
            return saved;
        },
    };
})();
/* END support:features/invoice_handoff/invoice_handoff.online.js */

/* BEGIN support:features/invoice_handoff/invoice_handoff.offline.js */
/* Offline adapter for cashier handoff draft persistence. */
(function () {
    "use strict";

    const ns = window.WMN_POS;
    ns.Features.InvoiceHandoff = ns.Features.InvoiceHandoff || {};

    ns.Features.InvoiceHandoff.Offline = {
        async saveDraft(ctrl, doc) {
            const storage = window.wmnPOSOffline;
            if (!storage?.saveInvoice || !storage?.bulkPut || !storage?.STORES?.invoice_queue) {
                throw new Error("Offline invoice storage is not available");
            }

            const row = await storage.saveInvoice(doc, ctrl);
            row.queue_kind = "draft";
            row.status = "draft";
            row.last_error = "";
            row.invoice = row.invoice || doc;
            row.invoice.__wmn_saved_as_draft = true;
            row.invoice.docstatus = 0;

            await storage.bulkPut(storage.STORES.invoice_queue, [row]);
            if (typeof window.wmn_notify_offline_queue_changed === "function") {
                window.wmn_notify_offline_queue_changed();
            }
            return row.invoice;
        },
    };
})();
/* END support:features/invoice_handoff/invoice_handoff.offline.js */

/* BEGIN support:features/return/return.common.js */
/* Shared return ownership for WMN POS. No storage or server calls live here. */
(function () {
    "use strict";

    const ns = window.WMN_POS;
    ns.Features.Return = ns.Features.Return || {};

    const EPSILON = 0.000001;

    function text(value) {
        return String(value || "").trim();
    }

    function invoiceIdentities(doc) {
        doc = doc || {};
        const values = [
            doc.name,
            doc.__wmn_display_name,
            doc.__wmn_queue_offline_id,
            doc.__wmn_server_name,
            doc.__wmn_original_name,
            doc.__wmn_return_against_offline_id,
            doc.wmn_offline_sync_id,
            doc.custom_offline_id,
        ];
        return new Set(values.map(text).filter(Boolean));
    }

    function returnReferenceField(doctype) {
        return text(doctype) === "POS Invoice" ? "pos_invoice_item" : "sales_invoice_item";
    }

    function sourceRowReference(sourceDoc, row) {
        const fieldname = returnReferenceField(sourceDoc?.doctype);
        return text(row?.[fieldname] || row?.__wmn_source_item_row || "");
    }

    function itemFingerprint(row) {
        row = row || {};
        return [
            text(row.item_code),
            text(row.uom),
            text(row.warehouse),
            text(row.batch_no),
            text(row.serial_no),
        ].join("::");
    }

    function isSubmittedSource(doc) {
        doc = doc || {};
        return cint(doc.docstatus || 0) === 1 || doc.__wmn_local_submitted === true;
    }

    function canOfferReturn(doc) {
        doc = doc || {};
        if (!isSubmittedSource(doc)) return false;
        if (cint(doc.is_return || 0) === 1) return false;
        return Array.isArray(doc.items) && doc.items.some((row) => Math.abs(flt(row?.qty || 0)) > EPSILON);
    }

    function returnMatchesSource(returnDoc, sourceDoc) {
        if (!returnDoc || cint(returnDoc.is_return || 0) !== 1) return false;
        const sourceIds = invoiceIdentities(sourceDoc);
        const returnAgainstValues = [
            returnDoc.return_against,
            returnDoc.__wmn_return_against_offline_id,
        ].map(text).filter(Boolean);
        return returnAgainstValues.some((value) => sourceIds.has(value));
    }

    function sourceBaseNetRate(row) {
        row = row || {};
        const qty = Math.abs(flt(row.qty || 0));
        if (qty <= EPSILON) return flt(row.net_rate || row.rate || 0);

        // ERPNext resets net values before applying invoice-level discount.
        // Reconstruct that pre-invoice-discount net rate from the submitted row.
        const distributed = flt(row.distributed_discount_amount || 0);
        const finalNetAmount = flt(
            row.net_amount !== undefined ? row.net_amount : (row.amount || 0)
        );
        const preInvoiceDiscountNetAmount = finalNetAmount + distributed;
        if (Math.abs(preInvoiceDiscountNetAmount) > EPSILON || Math.abs(finalNetAmount) > EPSILON) {
            return preInvoiceDiscountNetAmount / flt(row.qty || 1);
        }

        return flt(row.net_rate || row.rate || 0);
    }

    function financialSnapshot(sourceDoc) {
        sourceDoc = sourceDoc || {};
        const fields = [
            "total_qty",
            "total",
            "net_total",
            "base_total",
            "base_net_total",
            "total_taxes_and_charges",
            "base_total_taxes_and_charges",
            "discount_amount",
            "base_discount_amount",
            "grand_total",
            "base_grand_total",
            "rounded_total",
            "base_rounded_total",
            "rounding_adjustment",
            "base_rounding_adjustment",
            "paid_amount",
            "base_paid_amount",
            "outstanding_amount",
        ];
        const values = {};
        fields.forEach((fieldname) => {
            if (sourceDoc[fieldname] !== undefined && sourceDoc[fieldname] !== null) {
                values[fieldname] = flt(sourceDoc[fieldname] || 0);
            }
        });

        return {
            values,
            taxes: (sourceDoc.taxes || []).map((tax) => ({
                idx: cint(tax.idx || 0),
                tax_amount: flt(tax.tax_amount || 0),
                base_tax_amount: flt(tax.base_tax_amount || tax.tax_amount || 0),
                tax_amount_after_discount_amount: flt(
                    tax.tax_amount_after_discount_amount !== undefined
                        ? tax.tax_amount_after_discount_amount
                        : tax.tax_amount || 0
                ),
                base_tax_amount_after_discount_amount: flt(
                    tax.base_tax_amount_after_discount_amount !== undefined
                        ? tax.base_tax_amount_after_discount_amount
                        : (tax.base_tax_amount !== undefined ? tax.base_tax_amount : tax.tax_amount || 0)
                ),
                total: flt(tax.total || 0),
                base_total: flt(tax.base_total !== undefined ? tax.base_total : tax.total || 0),
            })),
        };
    }

    ns.Features.Return.Common = {
        EPSILON,
        invoiceIdentities,
        returnReferenceField,
        sourceRowReference,
        itemFingerprint,
        isSubmittedSource,
        canOfferReturn,
        returnMatchesSource,
        sourceBaseNetRate,
        financialSnapshot,
    };
})();
/* END support:features/return/return.common.js */

/* BEGIN support:features/return/return.offline.js */
/* Offline return state derived only from the local invoice queue. */
(function () {
    "use strict";

    const ns = window.WMN_POS;
    ns.Features.Return = ns.Features.Return || {};
    const Common = ns.Features.Return.Common;

    function rawInvoice(row) {
        return row?.invoice || row?.doc || row?.data || row || null;
    }

    async function getQueueRows() {
        const storage = window.wmnPOSOffline;
        if (!storage?.getAllCached || !storage?.STORES?.invoice_queue) return [];
        return (await storage.getAllCached(storage.STORES.invoice_queue)) || [];
    }

    function resolveSourceItem(sourceDoc, returnRow, sourceByName, sourceByFingerprint) {
        const reference = Common.sourceRowReference(sourceDoc, returnRow);
        if (reference && sourceByName.has(reference)) return sourceByName.get(reference);

        const fingerprint = Common.itemFingerprint(returnRow);
        const candidates = sourceByFingerprint.get(fingerprint) || [];
        if (candidates.length === 1) return candidates[0];

        const sameItem = (sourceDoc.items || []).filter((row) => String(row.item_code || "") === String(returnRow.item_code || ""));
        return sameItem.length === 1 ? sameItem[0] : null;
    }

    async function getReturnState(sourceDoc) {
        sourceDoc = sourceDoc || {};
        const sourceItems = (sourceDoc.items || []).filter((row) => row && Math.abs(flt(row.qty || 0)) > Common.EPSILON);
        const sourceByName = new Map();
        const sourceByFingerprint = new Map();
        const stateByRow = new Map();

        sourceItems.forEach((row, index) => {
            const rowName = String(row.name || `__idx_${index + 1}`);
            sourceByName.set(String(row.name || ""), row);
            const fingerprint = Common.itemFingerprint(row);
            if (!sourceByFingerprint.has(fingerprint)) sourceByFingerprint.set(fingerprint, []);
            sourceByFingerprint.get(fingerprint).push(row);
            stateByRow.set(rowName, {
                source_row: row,
                source_qty: Math.abs(flt(row.qty || 0)),
                returned_qty: 0,
                remaining_qty: Math.abs(flt(row.qty || 0)),
            });
        });

        const queueRows = await getQueueRows();
        for (const queueRow of queueRows) {
            const returnDoc = rawInvoice(queueRow);
            if (!Common.returnMatchesSource(returnDoc, sourceDoc)) continue;

            for (const returnRow of returnDoc.items || []) {
                const sourceRow = resolveSourceItem(sourceDoc, returnRow, sourceByName, sourceByFingerprint);
                if (!sourceRow) continue;
                const sourceKey = String(sourceRow.name || `__idx_${cint(sourceRow.idx || 0)}`);
                const itemState = stateByRow.get(sourceKey);
                if (!itemState) continue;
                itemState.returned_qty += Math.abs(flt(returnRow.qty || 0));
            }
        }

        const items = Array.from(stateByRow.values()).map((itemState) => {
            itemState.returned_qty = Math.min(itemState.source_qty, Math.max(0, flt(itemState.returned_qty || 0)));
            itemState.remaining_qty = Math.max(0, itemState.source_qty - itemState.returned_qty);
            return itemState;
        });

        return {
            source: sourceDoc,
            submitted: Common.isSubmittedSource(sourceDoc),
            is_return: cint(sourceDoc.is_return || 0) === 1,
            items,
            returnable: Common.canOfferReturn(sourceDoc) && items.some((row) => row.remaining_qty > Common.EPSILON),
        };
    }

    async function getReturnedQty(sourceDoc, sourceItem) {
        const state = await getReturnState(sourceDoc);
        const sourceName = String(sourceItem?.name || "");
        const exact = state.items.find((row) => String(row.source_row?.name || "") === sourceName);
        if (exact) return exact.returned_qty;

        const fingerprint = Common.itemFingerprint(sourceItem);
        const matches = state.items.filter((row) => Common.itemFingerprint(row.source_row) === fingerprint);
        return matches.length === 1 ? matches[0].returned_qty : 0;
    }

    async function isInvoiceReturnable(sourceDoc) {
        const state = await getReturnState(sourceDoc);
        return !!state.returnable;
    }

    function isFullOriginalReturn(returnState) {
        const items = returnState?.items || [];
        if (!items.length) return false;
        return items.every((state) => (
            Math.abs(flt(state.returned_qty || 0)) <= Common.EPSILON &&
            Math.abs(flt(state.remaining_qty || 0) - flt(state.source_qty || 0)) <= Common.EPSILON
        ));
    }

    function buildReturnTaxRows(sourceDoc, targetDoc) {
        return (sourceDoc.taxes || []).map((tax, idx) => {
            const returnTax = Object.assign({}, tax, {
                name: "OFFLINE-RETURN-TAX-" + Date.now() + "-" + idx,
                parent: targetDoc.name,
                parenttype: targetDoc.doctype,
                parentfield: "taxes",
                idx: idx + 1,
            });

            if (String(returnTax.charge_type || "") === "Actual") {
                returnTax.tax_amount = -flt(tax.tax_amount || 0);
                returnTax.base_tax_amount = -flt(
                    tax.base_tax_amount !== undefined ? tax.base_tax_amount : tax.tax_amount || 0
                );
            }
            return returnTax;
        });
    }

    function buildReturnItems(sourceDoc, targetDoc, returnState) {
        const referenceField = Common.returnReferenceField(targetDoc.doctype);
        return (returnState.items || [])
            .filter((state) => flt(state.remaining_qty || 0) > Common.EPSILON)
            .map((state, idx) => {
                const row = state.source_row || {};
                const returnQty = Math.max(0, flt(state.remaining_qty || 0));
                const sourceQty = Math.max(Common.EPSILON, Math.abs(flt(state.source_qty || row.qty || 0)));
                const conversionFactor = Math.abs(flt(row.conversion_factor || 1)) || 1;
                const sourceStockQty = Math.abs(flt(
                    row.stock_qty !== undefined ? row.stock_qty : sourceQty * conversionFactor
                ));
                const ratio = Math.min(1, returnQty / sourceQty);
                const returnRow = Object.assign({}, row, {
                    name: "OFFLINE-RETURN-ROW-" + Date.now() + "-" + idx,
                    qty: -returnQty,
                    stock_qty: -(sourceStockQty * ratio),
                    returned_qty: 0,
                    parent: targetDoc.name,
                    parenttype: targetDoc.doctype,
                    parentfield: "items",
                    idx: idx + 1,
                    pricing_rules: null,
                    __wmn_source_item_row: row.name || "",
                    __wmn_return_source_qty: sourceQty,
                    __wmn_return_base_net_rate: Common.sourceBaseNetRate(row),
                });

                if (referenceField) returnRow[referenceField] = row.name;

                // ERPNext calculate_item_values starts from rate/amount and a clean net state.
                // Do not carry the source's already distributed invoice discount into the return.
                returnRow.amount = flt(returnRow.qty || 0) * flt(returnRow.rate || returnRow.price_list_rate || 0);
                returnRow.base_amount = flt(returnRow.qty || 0) * flt(returnRow.base_rate || returnRow.rate || 0);
                returnRow.net_rate = flt(returnRow.__wmn_return_base_net_rate || returnRow.rate || 0);
                returnRow.net_amount = flt(returnRow.qty || 0) * returnRow.net_rate;
                returnRow.base_net_rate = flt(
                    row.base_net_rate && row.net_rate
                        ? returnRow.net_rate * (flt(row.base_net_rate) / flt(row.net_rate))
                        : returnRow.net_rate
                );
                returnRow.base_net_amount = flt(returnRow.qty || 0) * returnRow.base_net_rate;
                returnRow.distributed_discount_amount = 0;
                return returnRow;
            });
    }

    function buildReturnPayments(sourceDoc, targetDoc, zeroPaymentReturn, fallbackPaymentMethod) {
        const rows = (sourceDoc.payments || [])
            .filter((row) => row && row.mode_of_payment)
            .map((row, idx) => ({
                doctype: row.doctype || "Sales Invoice Payment",
                name: "OFFLINE-RETURN-PAY-" + Date.now() + "-" + idx,
                parent: targetDoc.name,
                parenttype: targetDoc.doctype,
                parentfield: "payments",
                idx: idx + 1,
                mode_of_payment: row.mode_of_payment,
                type: row.type || "",
                account: row.account || "",
                default: row.default,
                amount: zeroPaymentReturn ? 0 : -flt(row.amount || 0),
                base_amount: zeroPaymentReturn
                    ? 0
                    : -flt(row.base_amount !== undefined ? row.base_amount : row.amount || 0),
            }));

        const sourcePaidAmount = flt(sourceDoc.paid_amount || 0);
        const hasMappedPayment = rows.some((row) => Math.abs(flt(row.amount || 0)) > Common.EPSILON);
        if (!zeroPaymentReturn && Math.abs(sourcePaidAmount) > Common.EPSILON && !hasMappedPayment) {
            const fallback = fallbackPaymentMethod || null;
            if (fallback?.mode_of_payment) {
                rows.push({
                    doctype: "Sales Invoice Payment",
                    name: "OFFLINE-RETURN-PAY-" + Date.now() + "-fallback",
                    parent: targetDoc.name,
                    parenttype: targetDoc.doctype,
                    parentfield: "payments",
                    idx: rows.length + 1,
                    mode_of_payment: fallback.mode_of_payment,
                    type: fallback.type || "",
                    account: fallback.account || "",
                    default: fallback.default,
                    amount: -Math.abs(sourcePaidAmount),
                    base_amount: -Math.abs(flt(sourceDoc.base_paid_amount || sourcePaidAmount)),
                });
            }
        }
        return rows;
    }

    function buildReturnDocument(sourceDoc, targetDoc, returnState, options = {}) {
        sourceDoc = sourceDoc || {};
        targetDoc = targetDoc || {};
        returnState = returnState || { items: [] };

        targetDoc.is_return = 1;
        targetDoc.return_against = sourceDoc.name;
        targetDoc.ignore_pricing_rule = 1;
        targetDoc.pricing_rules = [];
        targetDoc.customer = sourceDoc.customer;
        targetDoc.customer_name = sourceDoc.customer_name;
        targetDoc.apply_discount_on = sourceDoc.apply_discount_on || targetDoc.apply_discount_on || "Grand Total";
        targetDoc.additional_discount_percentage = flt(sourceDoc.additional_discount_percentage || 0);
        targetDoc.discount_amount = -flt(sourceDoc.discount_amount || 0);
        targetDoc.base_discount_amount = -flt(
            sourceDoc.base_discount_amount !== undefined
                ? sourceDoc.base_discount_amount
                : sourceDoc.discount_amount || 0
        );
        targetDoc.taxes_and_charges = sourceDoc.taxes_and_charges || "";
        targetDoc.tax_category = sourceDoc.tax_category || "";
        targetDoc.taxes = buildReturnTaxRows(sourceDoc, targetDoc);
        targetDoc.items = buildReturnItems(sourceDoc, targetDoc, returnState);
        targetDoc.__wmn_return_source_financial_snapshot = Common.financialSnapshot(sourceDoc);
        targetDoc.__wmn_return_source_payment_data = (sourceDoc.payments || [])
            .filter((row) => row && row.mode_of_payment)
            .map((row) => ({
                mode_of_payment: row.mode_of_payment,
                amount: flt(row.amount || 0),
            }));
        targetDoc.__wmn_return_exact_source_snapshot_eligible = isFullOriginalReturn(returnState);
        targetDoc.__wmn_return_exact_source_item_count = (sourceDoc.items || []).filter(
            (row) => row && Math.abs(flt(row.qty || 0)) > Common.EPSILON
        ).length;
        targetDoc.payments = buildReturnPayments(
            sourceDoc,
            targetDoc,
            options.zero_payment_return === true,
            options.fallback_payment_method || null
        );
        return targetDoc;
    }

    function applyExactFinancialSnapshotIfEligible(doc) {
        if (!doc || cint(doc.is_return || 0) !== 1) return false;
        if (doc.__wmn_return_exact_source_snapshot_eligible !== true) return false;
        const snapshot = doc.__wmn_return_source_financial_snapshot;
        if (!snapshot?.values) return false;

        const expectedCount = cint(doc.__wmn_return_exact_source_item_count || 0);
        if (!expectedCount || (doc.items || []).length !== expectedCount) return false;
        const quantitiesStillMatch = (doc.items || []).every((row) => (
            flt(row.qty || 0) < 0 &&
            Math.abs(Math.abs(flt(row.qty || 0)) - Math.abs(flt(row.__wmn_return_source_qty || 0))) <= Common.EPSILON
        ));
        if (!quantitiesStillMatch) return false;

        const reverseFields = [
            "total_qty",
            "total",
            "net_total",
            "base_total",
            "base_net_total",
            "total_taxes_and_charges",
            "base_total_taxes_and_charges",
            "discount_amount",
            "base_discount_amount",
            "grand_total",
            "base_grand_total",
            "rounded_total",
            "base_rounded_total",
            "rounding_adjustment",
            "base_rounding_adjustment",
        ];
        reverseFields.forEach((fieldname) => {
            if (Object.prototype.hasOwnProperty.call(snapshot.values, fieldname)) {
                doc[fieldname] = -flt(snapshot.values[fieldname] || 0);
            }
        });

        (doc.taxes || []).forEach((tax, idx) => {
            const sourceTax = (snapshot.taxes || [])[idx];
            if (!sourceTax) return;
            [
                "tax_amount",
                "base_tax_amount",
                "tax_amount_after_discount_amount",
                "base_tax_amount_after_discount_amount",
                "total",
                "base_total",
            ].forEach((fieldname) => {
                tax[fieldname] = -flt(sourceTax[fieldname] || 0);
            });
        });

        let paidAmount = 0;
        let basePaidAmount = 0;
        (doc.payments || []).forEach((payment) => {
            paidAmount += flt(payment.amount || 0);
            basePaidAmount += flt(payment.base_amount !== undefined ? payment.base_amount : payment.amount || 0);
        });
        doc.paid_amount = paidAmount;
        doc.base_paid_amount = basePaidAmount;
        const payable = doc.rounded_total !== undefined && doc.rounded_total !== null && flt(doc.rounded_total || 0) !== 0
            ? flt(doc.rounded_total || 0)
            : flt(doc.grand_total || 0);
        doc.outstanding_amount = payable - paidAmount;
        doc.change_amount = 0;
        doc.base_change_amount = 0;
        return true;
    }

    ns.Features.Return.Offline = {
        getReturnState,
        getReturnedQty,
        isInvoiceReturnable,
        buildReturnDocument,
        applyExactFinancialSnapshotIfEligible,
    };
})();
